-- ============================================================
-- 0048 — Curadoria dos textos-base da RNC: Reformas (RF)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- RF-01 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a reforma alterar sistemas estruturais ou de segurança sem ART/RRT emitida e recolhida',
  texto_fundamentacao_normativa = 'Toda reforma em edificação deve ser precedida de plano de reforma acompanhado de Anotação de Responsabilidade Técnica (ART, junto ao CREA) ou Registro de Responsabilidade Técnica (RRT, junto ao CAU), que vincula um profissional habilitado à autoria e à execução dos serviços. Aplica-se a NBR 16280 (reforma em edificações — sistema de gestão de reformas), que exige o plano de reforma, a documentação técnica e, quando aplicável, a aprovação do condomínio ou do responsável legal pela edificação, em conformidade com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério integra o plano de inspeção da obra e constitui requisito documental de aceitação para autorização do início dos serviços.',
  texto_risco_consequencia = 'A ausência de plano de reforma com ART/RRT e das aprovações exigíveis retira a responsabilização técnica formal sobre os serviços, expõe a obra a embargo e sanções administrativas e pode invalidar coberturas de seguro, além de permitir intervenções sem análise prévia de segurança estrutural e de uso da edificação. A permanência da condição mantém a reforma em situação irregular até a devida regularização documental. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar e formalizar o plano de reforma conforme a NBR 16280, com a respectiva ART/RRT emitida e recolhida por profissional habilitado; (ii) obter as aprovações do condomínio ou do responsável legal quando aplicável, arquivando os comprovantes no dossiê da obra; (iii) evidenciar a regularização com o registro fotográfico ({{evidencia_foto_correcao}}) da documentação afixada/protocolada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se os serviços já tiverem iniciado sem qualquer registro cautelar da área e da vizinhança',
  texto_fundamentacao_normativa = 'A vistoria cautelar consiste no levantamento fotográfico e descritivo do estado as-is da área a ser reformada e das áreas vizinhas passíveis de dano (paredes, revestimentos, esquadrias e elementos lindeiros) antes do início dos serviços, constituindo prova pré-existente para eventual imputação de responsabilidade por danos. Trata-se de boa prática consolidada de gestão de reformas e demolições, alinhada às exigências de planejamento e controle da NBR 16280 e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério ''as-is fotográfico da área e vizinhança antes do início'' integra o plano de inspeção e é requisito verificável de aceitação da etapa preparatória.',
  texto_risco_consequencia = 'A falta de vistoria cautelar registrada impede distinguir danos pré-existentes daqueles causados pela reforma, fragilizando a defesa técnica em reclamações de vizinhos e podendo gerar responsabilização indevida, custos de reparação e litígios. A permanência da condição mantém a obra sem base probatória do estado inicial até que o registro seja produzido. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar a vistoria cautelar com relatório fotográfico datado e descritivo da área e das vizinhanças passíveis de dano, antes de qualquer intervenção adicional; (ii) colher, quando aplicável, ciência dos responsáveis pelas áreas vizinhas e arquivar o relatório no dossiê da obra; (iii) evidenciar a produção do registro cautelar ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — condição que precede a liberação da demolição; manter Crítica sempre que houver dúvida sobre a natureza estrutural ou viva de um elemento',
  texto_fundamentacao_normativa = 'O mapeamento prévio de interferências — elementos estruturais, instalações vivas (elétricas, hidráulicas, gás e dados) e componentes que não podem ser removidos — é condição para o planejamento seguro da demolição, evitando cortes indevidos e contatos acidentais. Fundamenta-se no critério do item, nas boas práticas de gestão de reformas e demolições e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define o que é passível ou não de remoção. O critério ''estrutura, instalações vivas e elementos que não podem ser removidos'' integra o plano de inspeção e constitui requisito verificável para liberação da etapa de demolição.',
  texto_risco_consequencia = 'A não identificação das interferências pode levar ao corte de elementos estruturais, ao rompimento de tubulações e ao contato com instalações energizadas ou pressurizadas, com risco de colapso parcial, choque elétrico, vazamento de gás, inundação e acidentes graves com pessoas. A permanência da condição mantém a demolição sob risco não controlado até o levantamento completo das interferências. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar e mapear todas as interferências no local, confrontando com o projeto executivo e com os as-built das instalações, sinalizando fisicamente o que não pode ser removido; (ii) definir com o projetista/responsável os limites de intervenção e registrar o mapa de interferências no plano de demolição; (iii) evidenciar o mapeamento e a sinalização com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para liberação e fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — risco imediato à vida; manter Crítica enquanto houver instalação energizada ou pressurizada na frente de demolição',
  texto_fundamentacao_normativa = 'Antes de qualquer demolição, os circuitos elétricos e as tubulações (água, esgoto, gás) da área devem ser desativados, isolados e, no caso elétrico, desenergizados, bloqueados e testados quanto à ausência de tensão. Aplicam-se a NR-10 (segurança em instalações e serviços em eletricidade), que exige desenergização e medidas de bloqueio e sinalização antes de intervenções, e o critério do item, complementados pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério ''circuitos e tubulações isolados antes da demolição'' integra o plano de inspeção e é requisito de aceitação prévia à liberação da frente de serviço.',
  texto_risco_consequencia = 'A demolição sobre instalações ainda ativas expõe os trabalhadores a choque elétrico, arco elétrico, queimaduras, vazamento de gás com risco de incêndio ou explosão e alagamento por rompimento de tubulação sob carga, com potencial de acidente fatal e danos ao patrimônio. A permanência da condição mantém a frente de trabalho sob risco grave e iminente até a efetiva desativação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) desenergizar, bloquear, sinalizar e testar a ausência de tensão nos circuitos elétricos e fechar/isolar as tubulações de água e gás da área, conforme a NR-10 e os procedimentos da obra; (ii) confirmar a desativação com o responsável técnico e liberar a frente por meio de permissão de trabalho documentada; (iii) evidenciar o isolamento e o bloqueio com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — elevar/priorizar tratamento imediato quando houver risco de instabilização de elementos remanescentes ou de terceiros',
  texto_fundamentacao_normativa = 'A demolição deve seguir sequência planejada que preserve a estabilidade dos elementos remanescentes, com escoramento onde a retirada de um componente possa comprometer o equilíbrio da estrutura. Aplica-se a NR-18 (segurança e saúde no trabalho na indústria da construção), que estabelece requisitos para serviços de demolição, incluindo planejamento, isolamento da área e escoramento quando necessário, em conjunto com o critério do item e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério ''sequência sem impacto estrutural; escoramento quando necessário'' integra o plano de inspeção e é requisito verificável de execução da etapa.',
  texto_risco_consequencia = 'A demolição sem sequência controlada e sem escoramento pode provocar desequilíbrio e colapso parcial ou total de elementos remanescentes, queda de materiais e soterramento, com risco de lesões graves ou fatais a trabalhadores e a terceiros, além de danos a áreas vizinhas. A permanência da condição mantém a estrutura em situação de instabilidade até a adoção das medidas de contenção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) estabelecer e seguir a sequência de demolição de cima para baixo e por trechos, isolando a área e removendo pessoas não essenciais; (ii) implantar escoramento/contenção dos elementos que possam ser afetados, conforme definição do responsável técnico, antes de prosseguir; (iii) evidenciar a sequência adotada e o escoramento executado com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — condição que não admite prosseguimento; manter Crítica até anuência formal do projetista para qualquer remoção ou abertura',
  texto_fundamentacao_normativa = 'Nenhum elemento estrutural (pilares, vigas, lajes, paredes portantes) pode ser removido, cortado ou ter aberturas executadas sem projeto específico e anuência formal do projetista estrutural, dado o impacto direto sobre a capacidade de carga e a estabilidade global da edificação. Fundamenta-se no critério do item, nas boas práticas de engenharia estrutural e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define os elementos que integram o sistema estrutural. O critério ''nenhuma remoção/abertura sem projeto e anuência do projetista'' integra o plano de inspeção e constitui requisito de aceitação inegociável da etapa.',
  texto_risco_consequencia = 'A remoção ou abertura de elementos estruturais sem projeto e anuência do projetista pode reduzir a capacidade portante, redistribuir esforços de forma não prevista e provocar fissuração, deformações excessivas ou colapso estrutural, com risco à vida dos ocupantes e de terceiros e comprometimento definitivo da edificação. A permanência da condição mantém a estrutura sob risco até avaliação e deliberação do projetista. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender imediatamente qualquer intervenção sobre elementos estruturais e isolar a área afetada; (ii) submeter a situação ao projetista estrutural para avaliação, obtendo projeto de reforço/adequação e anuência formal antes de qualquer prosseguimento; (iii) evidenciar a preservação dos elementos e/ou a solução aprovada com registro fotográfico ({{evidencia_foto_correcao}}) e documento do projetista, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em caso de descarte irregular, ausência de MTR quando exigível ou mistura de resíduos perigosos',
  texto_fundamentacao_normativa = 'Os resíduos da construção e demolição devem ser segregados na origem por classe e destinados a locais licenciados, com emissão do Manifesto de Transporte de Resíduos (MTR) quando aplicável. Aplica-se a Resolução CONAMA 307 (gestão dos resíduos da construção civil), que estabelece a classificação (classes A, B, C e D) e a obrigatoriedade de destinação ambientalmente adequada, complementada pelas exigências do órgão ambiental local e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério ''CONAMA 307; MTR quando aplicável'' integra o plano de inspeção e é requisito verificável de conformidade ambiental da etapa.',
  texto_risco_consequencia = 'A ausência de segregação e destinação adequada do entulho pode gerar descarte irregular, contaminação, autuações e multas ambientais, além de responsabilização do gerador pela destinação incorreta e da mistura de resíduos perigosos (classe D) com inertes. A permanência da condição mantém a obra em não conformidade ambiental até a correta gestão dos resíduos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) segregar os resíduos por classe (A, B, C e D) em baias/contêineres identificados, isolando os resíduos perigosos; (ii) destinar cada classe a receptor/aterro licenciado, emitindo e arquivando o MTR e os comprovantes de destinação quando aplicável; (iii) evidenciar a segregação e a destinação com registro fotográfico ({{evidencia_foto_correcao}}) e documentação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em caso de reincidência, notificação formal de vizinhos/condomínio ou exposição de trabalhadores a poeira e ruído acima do tolerável',
  texto_fundamentacao_normativa = 'A reforma deve controlar a emissão de poeira, o nível de ruído e o horário de execução dos serviços, respeitando o regulamento interno do condomínio ou do local e a legislação municipal de sossego e limpeza. Fundamenta-se no critério do item, nas boas práticas de convivência e higiene ocupacional e no planejamento da obra, alinhados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} quando este disciplinar logística e horários. O critério ''regras do condomínio/local respeitadas'' integra o plano de inspeção e é requisito verificável de conformidade operacional da etapa.',
  texto_risco_consequencia = 'O descontrole de poeira, ruído e horários pode gerar reclamações e notificações de vizinhos e do condomínio, embargo dos serviços, exposição de trabalhadores e ocupantes a particulados e ruído e deterioração da relação com o entorno, com risco de paralisação e sanções. A permanência da condição mantém o incômodo e a não conformidade ativos até a adoção das medidas de controle. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar medidas de contenção de poeira (umidificação, enclausuramento, telas e limpeza frequente) e de atenuação de ruído, fornecendo EPIs adequados à equipe; (ii) ajustar a execução dos serviços ruidosos aos horários permitidos pelo condomínio/local e comunicar previamente os afetados; (iii) evidenciar as medidas adotadas com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-01' and item_numero = 8;

-- RF-02 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a etapa executada fora de sequência interferir em serviços estruturais ou de segurança já liberados, ou quando houver alteração de escopo executada sem reaprovação.',
  texto_fundamentacao_normativa = 'A execução da reforma deve obedecer à sequência de etapas aprovada no plano de reforma, e toda alteração de escopo ou de ordem executiva deve ser submetida a nova aprovação antes de prosseguir. Aplica-se a NBR 16280 (reforma em edificações — sistema de gestão), que exige plano de reforma formalizado, controle das etapas e registro das alterações, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sequência aprovada seguida; alterações reaprovadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A execução fora da sequência aprovada ou a introdução de alterações sem reaprovação pode comprometer interdependências entre serviços, gerar retrabalho, invalidar liberações já concedidas e afastar a obra das condições de segurança previstas, com sobrecusto e atraso de cronograma. A permanência da condição mantém a reforma em desvio de gestão até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper o avanço da etapa em desvio e confrontar o executado com a sequência definida no plano de reforma aprovado; (ii) submeter formalmente qualquer alteração de escopo ou de ordem executiva à reaprovação do responsável técnico antes de retomar os serviços; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) e atualização do plano de reforma, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica por envolver segurança estrutural; rebaixar a Maior apenas se o reforço for de caráter não resistente e houver comprovação de que a estabilidade não depende do elemento em questão.',
  texto_fundamentacao_normativa = 'Os reforços estruturais devem ser executados estritamente conforme o projeto específico de reforço e acompanhados e registrados durante toda a execução, por se tratar de intervenção que altera o comportamento resistente da edificação. Aplica-se a NBR 16280 (reforma em edificações), que condiciona intervenções com repercussão estrutural a projeto e responsável técnico habilitado, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define materiais, geometria e sequência de execução do reforço. O critério "Execução acompanhada e registrada" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Reforço estrutural executado em desacordo com o projeto ou sem acompanhamento e registro pode não restabelecer a capacidade resistente pretendida, mascarar patologias e comprometer a estabilidade da edificação, com risco à segurança de pessoas e ao patrimônio. A permanência da condição mantém a estrutura em situação de incerteza quanto à sua integridade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar os serviços que dependam do reforço e confrontar o executado com o projeto estrutural específico, quanto a materiais, dimensões e ancoragens; (ii) corrigir ou complementar o reforço conforme orientação do responsável técnico estrutural, garantindo acompanhamento contínuo; (iii) evidenciar a execução com registro fotográfico ({{evidencia_foto_correcao}}) e memória/relatório de acompanhamento assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a instalação servir a sistemas de segurança (incêndio, gás, aterramento) ou quando o ensaio não realizado impedir a liberação para uso.',
  texto_fundamentacao_normativa = 'As novas instalações prediais devem ser submetidas a ensaios de aceitação antes da liberação: as instalações hidráulicas por ensaio de estanqueidade/pressão e as instalações elétricas por verificação de isolamento, com relatórios formais. Aplicam-se a NBR 5626 (sistemas prediais de água fria e água quente), que prevê ensaio de pressão/estanqueidade da tubulação, e a NBR 5410 (instalações elétricas de baixa tensão), que exige a verificação da resistência de isolamento, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Pressão hidráulica e isolamento elétrico com relatórios" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A liberação de instalações sem os ensaios de estanqueidade hidráulica e de isolamento elétrico, devidamente documentados, pode permitir vazamentos ocultos, infiltrações, curtos-circuitos e risco de choque ou incêndio após a ocupação, danificando os acabamentos recém-executados e ameaçando a segurança dos usuários. A permanência da condição mantém as instalações sem comprovação de conformidade até a efetiva realização e registro dos ensaios. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar os ensaios pendentes — teste de pressão/estanqueidade nas redes hidráulicas e medição de resistência de isolamento nas instalações elétricas; (ii) sanar as não conformidades detectadas e reensaiar os trechos corrigidos até a aprovação; (iii) evidenciar os resultados com registro fotográfico ({{evidencia_foto_correcao}}) e emissão dos relatórios de ensaio assinados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a interface não resolvida entre o novo e o existente afetar estanqueidade, estabilidade estrutural ou segurança de instalações.',
  texto_fundamentacao_normativa = 'As interfaces entre os serviços novos e a construção existente devem ser tecnicamente resolvidas e registradas, assegurando continuidade de desempenho entre o que foi mantido e o que foi executado. Na ausência de norma específica para cada interface, a exigência fundamenta-se no critério de aceitação do item, nas boas práticas de compatibilização de projetos e execução e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, complementados pela NBR 16280 (reforma em edificações) quanto à compatibilidade entre a intervenção e a edificação existente. O critério "Interfaces novo × antigo resolvidas e registradas" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Interfaces mal resolvidas entre o novo e o existente podem gerar juntas frágeis, trincas, infiltrações, degraus de nível e descontinuidades de instalações, comprometendo o desempenho e a durabilidade do conjunto e ensejando retrabalho após a entrega. A permanência da condição mantém pontos de fragilidade na ligação entre as partes até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear as interfaces novo × antigo pendentes e definir a solução técnica de ligação (tratamento de juntas, transições, arremates e compatibilização de instalações); (ii) executar as soluções definidas assegurando continuidade de desempenho e vedação; (iii) evidenciar a resolução com registro fotográfico ({{evidencia_foto_correcao}}) e detalhamento das soluções adotadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a divergência de material ou padrão for extensiva, reincidente ou afetar desempenho (impermeabilização, revestimentos de áreas molhadas) e não apenas o aspecto estético.',
  texto_fundamentacao_normativa = 'Os acabamentos devem reproduzir os materiais, as marcas e os padrões definidos no memorial descritivo e nas especificações contratadas, condição verificável por conferência física em campo. Por tratar-se de conformidade contratual e de especificação, a exigência fundamenta-se no critério de aceitação do item, no memorial descritivo/contrato e nas boas práticas de recebimento de materiais e serviços, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Materiais e padrões contratados conferidos" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A aplicação de acabamentos em desacordo com o memorial e as especificações contratadas caracteriza descumprimento contratual, pode reduzir a qualidade e a durabilidade esperadas e enseja glosa, substituição e retrabalho, além de insatisfação do contratante na entrega. A permanência da condição mantém o serviço em não conformidade com o contratado até a efetiva adequação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar os materiais e padrões aplicados com o memorial descritivo e as especificações contratadas, identificando as divergências; (ii) substituir ou readequar os acabamentos não conformes, ou formalizar a aprovação de eventual equivalência técnica pelo contratante; (iii) evidenciar a adequação com registro fotográfico ({{evidencia_foto_correcao}}) e confronto com o memorial, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando houver destinação irregular de resíduos, ausência de comprovação de destinação ou resíduos perigosos sem manifesto, dada a repercussão ambiental e legal.',
  texto_fundamentacao_normativa = 'Ao final da reforma a área deve ser entregue limpa e os resíduos gerados devem ter destinação adequada e comprovada. Aplica-se a Resolução CONAMA nº 307 (gestão dos resíduos da construção civil), que estabelece a triagem e a destinação ambientalmente adequada dos resíduos de construção e demolição, complementada pelo critério de aceitação do item e pelas boas práticas de gestão de resíduos da obra. O critério "Área entregue limpa; resíduos destinados" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A entrega da área sem limpeza adequada ou a destinação irregular dos resíduos expõe a obra a autuações ambientais, impede o uso pleno do espaço reformado e pode ocultar defeitos executivos sob entulho e sujeira, além de prejudicar a imagem do contratante. A permanência da condição mantém a área em situação inadequada de entrega e o passivo de resíduos em aberto até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar a limpeza fina da área reformada, removendo entulho, sobras e resíduos; (ii) promover a triagem e a destinação ambientalmente adequada dos resíduos, obtendo os comprovantes de destinação; (iii) evidenciar a conclusão com registro fotográfico ({{evidencia_foto_correcao}}) e os comprovantes de destinação dos resíduos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando as alterações não documentadas envolverem elementos estruturais, instalações embutidas ou traçados de rede cuja localização seja essencial à segurança e à manutenção futura.',
  texto_fundamentacao_normativa = 'As alterações efetivamente executadas na reforma devem ser documentadas sobre o cadastro original, produzindo o as built que registra a situação real da edificação após a intervenção. Aplica-se a NBR 16280 (reforma em edificações), que exige a documentação e a atualização dos registros da edificação decorrentes da reforma, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Alterações documentadas sobre o cadastro original" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência ou a incompletude do as built deixa a edificação sem registro fiel do que foi executado, dificultando manutenções, futuras intervenções e a localização segura de instalações embutidas, com risco de danos e de decisões técnicas baseadas em informação desatualizada. A permanência da condição mantém a documentação da edificação em divergência com o executado até a efetiva atualização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar em campo todas as alterações executadas frente ao cadastro original; (ii) elaborar e consolidar o as built da reforma, incorporando as modificações de arquitetura e instalações sobre o cadastro existente; (iii) evidenciar a entrega com registro fotográfico ({{evidencia_foto_correcao}}) e os arquivos do as built atualizados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ocupação ou o uso da edificação ocorrer sem o encerramento formal, dada a pendência de responsabilidades e de conformidade documental da reforma.',
  texto_fundamentacao_normativa = 'O encerramento da reforma deve ser formalizado por termo de entrega assinado, consolidando a conclusão dos serviços e a transferência de responsabilidade ao contratante. Aplica-se a NBR 16280 (reforma em edificações), que estabelece o encerramento documental da reforma e a formalização de sua conclusão, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e os demais documentos de entrega. O critério "Encerramento formal conforme NBR 16280" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A entrega da reforma sem termo assinado deixa indefinido o marco de conclusão e a transferência de responsabilidades, fragiliza o acionamento de garantias e pode gerar controvérsias contratuais quanto ao que foi efetivamente entregue e aceito. A permanência da condição mantém a reforma sem encerramento formal, com responsabilidades em aberto, até a efetiva assinatura do termo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar a documentação de encerramento (relatórios de ensaio, as built e comprovantes) que embasa a entrega; (ii) emitir o termo de entrega conforme a NBR 16280 e colher as assinaturas das partes; (iii) evidenciar o encerramento com registro fotográfico ({{evidencia_foto_correcao}}) e o termo de entrega assinado arquivado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'RF-02' and item_numero = 8;

